package com.djibtout.backend.entity;import jakarta.persistence.*;import java.time.*;
@Entity public class SellerNotification{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private User seller;private String title;@Column(length=1000)private String message;private boolean read=false;private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public User getSeller(){return seller;}public void setSeller(User v){seller=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public boolean isRead(){return read;}public void setRead(boolean v){read=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
